1	// Small C shim around the Vulkan compute path used by this program.
2	//
3	// Why this exists: Go's cgo forbids passing a Go struct across the C
4	// boundary when one of its fields is itself a pointer into other Go memory
5	// (the "Go pointer to Go pointer" check). Vulkan's *CreateInfo structs are
6	// built almost entirely out of such chains (pApplicationInfo,
7	// pQueueCreateInfos, pBindings, ...), so building them in Go and taking
8	// their address would trip that check on nearly every call. Building them
9	// here instead means every pointer crossing the Go/C boundary is either an
10	// opaque Vulkan handle or a flat byte buffer — both of which cgo allows.
11	#ifndef STRIX_HALO_VULKAN_SHIM_H
12	#define STRIX_HALO_VULKAN_SHIM_H
13	
14	#include <vulkan/vulkan.h>
