19	    uint32_t vendorID;
20	    uint32_t deviceID;
21	    VkPhysicalDeviceType deviceType;
22	    double timestampPeriod; // nanoseconds per timestamp tick (VkPhysicalDeviceLimits.timestampPeriod)
23	} ShimPhysicalDevice;
