    uint n;
    float eps;
} pc;

shared float rmsShared;

void main() {
    uint row = gl_WorkGroupID.x;
    if (row >= pc.rows) {
        return;
    }
    uint base = row * pc.n;
    uint tid = gl_LocalInvocationID.x;

    float sumSq = 0.0;
    for (uint i = tid; i < pc.n; i += gl_WorkGroupSize.x) {
        float v = x[base + i];
        sumSq += v * v;
    }
    float total = subgroupAdd(sumSq);
    if (subgroupElect()) {
        rmsShared = sqrt(total / float(pc.n) + pc.eps);
    }
    barrier();

    float rms = rmsShared;
    for (uint i = tid; i < pc.n; i += gl_WorkGroupSize.x) {
        y[base + i] = (x[base + i] / rms) * weight[i];
    }
}

